result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/vm/vm.py", "content": """"Stack-based bytecode virtual machine.

Executes programs produced by vm.compiler: (code, consts) where code is a
flat list of ints and consts is the constants pool. The VM keeps an operand
stack of ints and a locals array (one slot per source variable).

Runtime errors -- division by zero, stack underflow, unknown opcode,
out-of-range operands, missing HALT -- raise VmError carrying the
instruction pointer (ip) at which the fault occurred.
"""

from __future__ import annotations

import sys

from .compiler import (
    OP_ADD, OP_DIV, OP_EQ, OP_GT, OP_HALT, OP_JMP, OP_JZ, OP_LOAD,
    OP_LT, OP_MUL, OP_PRINT, OP_PUSH, OP_STORE, OP_SUB,
    _NARGS,
)


class VmError(Exception):
    def __init__(self, message: str, ip: int):
        super().__init__(f"{message} (at ip={ip})")
        self.message = message
        self.ip = ip


class VM:
    def __init__(self, code: list[int], consts: list[int], nlocals: int = 0,
                 out=None):
        self.code = code
        self.consts = consts
        self.stack: list[int] = []
        self.locals = [0] * nlocals
        self.out = out if out is not None else sys.stdout

    # -- operand stack helpers ---------------------------------------------
    def _pop(self, ip: int) -> int:
        if not self.stack:
            raise VmError("stack underflow", ip)
        return self.stack.pop()

    def _pop2(self, ip: int) -> tuple[int, int]:
        if len(self.stack) < 2:
            raise VmError("stack underflow", ip)
        b = self.stack.pop()
        a = self.stack.pop()
        return a, b  # a pushed first, b on top

    @staticmethod
    def _div(a: int, b: int, ip: int) -> int:
        if b == 0:
            raise VmError("division by zero", ip)
        q = abs(a) // abs(b)          # truncate toward zero, like C
        return -q if (a < 0) != (b < 0) else q

    # -- interpreter loop ----------------------------------------------------
    def run(self, max_steps: int | None = None) -> None:
        """Execute until HALT. Raises VmError on runtime faults."""
        code, consts = self.code, self.consts
        ip = 0
        steps = 0
        while True:
            if max_steps is not None:
                steps += 1
                if steps > max_steps:
                    raise VmError("step limit exceeded", ip)
            if ip >= len(code):
                raise VmError("fell off end of code without HALT", ip)
            op = code[ip]
            nargs = _NARGS.get(op)
            if nargs is None and op not in _ZERO_ARG_OPS:
                raise VmError(f"unknown opcode {op}", ip)

            if op == OP_PUSH:
                idx = code[ip + 1]
                if not 0 <= idx < len(consts):
                    raise VmError(f"constant index {idx} out of range", ip)
                self.stack.append(consts[idx])
                ip += 2
            elif op == OP_LOAD:
                slot = code[ip + 1]
                if not 0 <= slot < len(self.locals):
                    raise VmError(f"local slot {slot} out of range", ip)
                self.stack.append(self.locals[slot])
                ip += 2
            elif op == OP_STORE:
                slot = code[ip + 1]
                value = self._pop(ip)
                while len(self.locals) <= slot:
                    self.locals.append(0)
                self.locals[slot] = value
                ip += 2
            elif op == OP_JMP:
                ip = code[ip + 1]
            elif op == OP_JZ:
                target, value = code[ip + 1], self._pop(ip)
                ip = target if value == 0 else ip + 2
            elif op == OP_ADD:
                a, b = self._pop2(ip)
                self.stack.append(a + b)
                ip += 1
            elif op == OP_SUB:
                a, b = self._pop2(ip)
                self.stack.append(a - b)
                ip += 1
            elif op == OP_MUL:
                a, b = self._pop2(ip)
                self.stack.append(a * b)
                ip += 1
            elif op == OP_DIV:
                a, b = self._pop2(ip)
                self.stack.append(self._div(a, b, ip))
                ip += 1
            elif op == OP_LT:
                a, b = self._pop2(ip)
                self.stack.append(1 if a < b else 0)
                ip += 1
            elif op == OP_GT:
                a, b = self._pop2(ip)
                self.stack.append(1 if a > b else 0)
                ip += 1
            elif op == OP_EQ:
                a, b = self._pop2(ip)
                self.stack.append(1 if a == b else 0)
                ip += 1
            elif op == OP_PRINT:
                print(self._pop(ip), file=self.out)
                ip += 1
            elif op == OP_HALT:
                return


_ZERO_ARG_OPS = frozenset(
    {OP_ADD, OP_SUB, OP_MUL, OP_DIV, OP_LT, OP_GT, OP_EQ,
     OP_PRINT, OP_HALT}
)


def run(code: list[int], consts: list[int], nlocals: int | None = None,
        out=None, max_steps: int | None = 10_000_000) -> VM:
    """Convenience runner. Returns the VM (inspect .locals / .stack after)."""
    if nlocals is None:
        nlocals = max_slot(code) + 1 if code else 0
    vm = VM(code, consts, nlocals=nlocals, out=out)
    vm.run(max_steps=max_steps)
    return vm


def max_slot(code: list[int]) -> int:
    """Highest local slot referenced by LOAD/STORE in code (-1 if none)."""
    best = -1
    i = 0
    while i < len(code):
        op = code[i]
        if op in (OP_LOAD, OP_STORE):
            best = max(best, code[i + 1])
            i += 2
        else:
            i += 2 if op in _NARGS else 1
    return best
