import io

import pytest

from vm import compile_src, disasm, asm, run
from vm.compiler import OP_ADD, OP_HALT, OP_JMP, OP_JZ, OP_LOAD, OP_PRINT, \
    OP_PUSH, OP_STORE, OP_WHILE_MARKER if False else OP_LT  # noqa
from vm.vm import VmError


def execute(src: str) -> str:
    """Compile source, run it, return captured stdout."""
    code, consts = compile_src(src)
    out = io.StringIO()
    run(code, consts, out=out)
    return out.getvalue()


# ---------------------------------------------------------------------------
# (a) while-loop accumulator: sum 0..9 = 45
# ---------------------------------------------------------------------------
def test_while_sum_45():
    src = """
    x = 0;
    sum = 0;
    while (x < 10) {
        sum = sum + x;
        x = x + 1;
    }
    print(sum);
    """
    assert execute(src) == "45\n"


# ---------------------------------------------------------------------------
# (b) nested if/else
# ---------------------------------------------------------------------------
def test_nested_if_else():
    src = """
    a = 7;
    b = 3;
    if (a > b) {
        if (a == 7) {
            print(100);
        } else {
            print(200);
        }
    } else {
        if (b == 3) {
            print(300);
        } else {
            print(400);
        }
    }
    print(a * b);
    """
    assert execute(src) == "100\n21\n"


def test_if_else_false_branch():
    src = """
    x = 5;
    if (x == 10) { print(1); } else { print(2); }
    if (x < 5) { print(3); }
    print(9);
    """
    # second if has no else -> prints nothing for it
    assert execute(src) == "2\n9\n"


# ---------------------------------------------------------------------------
# (c) iterative fibonacci: fib(20) = 6765
# ---------------------------------------------------------------------------
def test_fib_iterative():
    src = """
    n = 20;
    a = 0;
    b = 1;
    i = 0;
    while (i < n) {
        t = a + b;
        a = b;
        b = t;
        i = i + 1;
    }
    print(a);
    """
    # after the loop a holds fib(n) with fib(0)=0, fib(1)=1
    assert execute(src) == "6765\n"


# ---------------------------------------------------------------------------
# arithmetic / comparison semantics
# ---------------------------------------------------------------------------
def test_arithmetic_and_precedence():
    src = "print(2 + 3 * 4);\nprint((2 + 3) * 4);\nprint(17 / 5);\nprint(-7 / 2);"
    assert execute(src) == "14\n20\n3\n-3\n"


def test_division_truncates_toward_zero():
    assert execute("print(-17 / 5);") == "-3\n"


# ---------------------------------------------------------------------------
# bytecode shape sanity + runtime errors carry ip
# ---------------------------------------------------------------------------
def test_simple_program_bytecode_shape():
    code, consts = compile_src("x = 1 + 2; print(x);")
    assert consts == [1, 2]
    assert code == [
        OP_PUSH, 0, OP_PUSH, 1, OP_ADD,      # 1 + 2
        OP_STORE, 0,                          # x =
        OP_LOAD, 0, OP_PRINT,                 # print(x)
        OP_HALT,
    ]


def test_div_by_zero_raises_with_ip():
    code, consts = compile_src("x = 0; y = 1 / x;")
    with pytest.raises(VmError) as exc:
        run(code, consts)
    assert exc.value.ip >= 0
    assert "division by zero" in exc.value.message


def test_stack_underflow_raises_with_ip():
    code = [OP_ADD, OP_HALT]   # ADD with empty stack
    with pytest.raises(VmError) as exc:
        run(code, [])
    assert exc.value.ip == 0


# ---------------------------------------------------------------------------
# disasm -> asm round trip
# ---------------------------------------------------------------------------
ROUND_TRIP_SOURCES = [
    "x = 0; sum = 0; while (x < 10) { sum = sum + x; x = x + 1; } print(sum);",
    """
    a = 7; b = 3;
    if (a > b) { if (a == 7) { print(100); } else { print(200); } }
    else { if (b == 3) { print(300); } else { print(400); } }
    """,
    """
    n = 20; a = 0; b = 1; i = 0;
    while (i < n) { t = a + b; a = b; b = t; i = i + 1; }
    print(a);
    """,
]


@pytest.mark.parametrize("src", ROUND_TRIP_SOURCES)
def test_disasm_asm_roundtrip(src):
    code, consts = compile_src(src)
    listing = disasm(code, consts)
    rt_code, rt_consts = asm(listing)
    assert rt_code == code
    assert rt_consts == consts


def test_disasm_listing_contains_mnemonics():
    code, consts = compile_src("x = 3; while (x > 0) { x = x - 1; }")
    text = disasm(code, consts)
    for mnemonic in ("PUSH", "LOAD", "STORE", "SUB", "GT", "JZ", "JMP",
                     "HALT"):
        assert mnemonic in text
    # assembler accepts its own listing verbatim
    assert asm(text)[0] == code
