        self.code[addr + 1] = len(self.code)

    # -- statements ---------------------------------------------------------
    def parse_program(self):
        while self.peek()[0] != "eof":
            self.statement()
        self.emit(OP_HALT)
        return self.code, self.consts

    def statement(self):
        kind = self.peek()[0]
        if kind == "{":
            self.block()
        elif kind == "if":
            self.if_stmt()
        elif kind == "while":
            self.while_stmt()
        elif kind == "print":
            self.print_stmt()
        elif kind == "ident":
            self.assign_stmt()
        else:
            raise CompileError(f"unexpected token {kind!r} at statement start")

    def block(self):
        self.expect("{")
        while self.peek()[0] != "}":
            self.statement()
        self.expect("}")

    def assign_stmt(self):
        name = self.expect("ident")[1]
        self.expect("=")
        self.expr()
